Here is the commit message:
bcachefs: Fix printbuf usage while atomic

Reported-by: syzbot+f765e51170cf13493f0b@syzkaller.appspotmail.com
Fixes: f12410bb7ddd ("bcachefs: Add an error message for insufficient rw journal devs")
Signed-off-by: Kent Overstreet <kent.overstreet@linux.dev>

Here is the root cause:
The bug arises from the improper handling of the `printbuf` structure in an atomic context, where concurrent access could lead to data corruption or unexpected behavior when printing error messages. The `atomic` member of the `printbuf` was not being incremented, which could result in the buffer being modified while it was being used for printing, leading to potential race conditions.

Here is the patch:

 void bch2_journal_space_available(struct journal *j)
 {
 	struct bch_fs *c = container_of(j, struct bch_fs, journal);
 	unsigned clean, clean_ondisk, total;
 	unsigned max_entry_size	 = min(j->buf[0].buf_size >> 9,
 				       j->buf[1].buf_size >> 9);
 	unsigned nr_online = 0, nr_devs_want;
 	bool can_discard = false;
 	int ret = 0;

 	lockdep_assert_held(&j->lock);

 	rcu_read_lock();
 	for_each_member_device_rcu(c, ca, &c->rw_devs[BCH_DATA_journal]) {
 		struct journal_device *ja = &ca->journal;

 		if (!ja->nr)
 			continue;

 		while (ja->dirty_idx != ja->cur_idx &&
 		       ja->bucket_seq[ja->dirty_idx] < journal_last_seq(j))
 			ja->dirty_idx = (ja->dirty_idx + 1) % ja->nr;

 		while (ja->dirty_idx_ondisk != ja->dirty_idx &&
 		       ja->bucket_seq[ja->dirty_idx_ondisk] < j->last_seq_ondisk)
 			ja->dirty_idx_ondisk = (ja->dirty_idx_ondisk + 1) % ja->nr;

 		if (ja->discard_idx != ja->dirty_idx_ondisk)
 			can_discard = true;

 		max_entry_size = min_t(unsigned, max_entry_size, ca->mi.bucket_size);
 		nr_online++;
 	}
 	rcu_read_unlock();

 	j->can_discard = can_discard;

 	if (nr_online < metadata_replicas_required(c)) {
 		struct printbuf buf = PRINTBUF;
+		buf.atomic++;
 		prt_printf(&buf, "insufficient writeable journal devices available: have %u, need %u\n"
 			   "rw journal devs:", nr_online, metadata_replicas_required(c));

 		rcu_read_lock();
 		for_each_member_device_rcu(c, ca, &c->rw_devs[BCH_DATA_journal])
 			prt_printf(&buf, " %s", ca->name);
 		rcu_read_unlock();

 		bch_err(c, "%s", buf.buf);
 		printbuf_exit(&buf);
 		ret = JOURNAL_ERR_insufficient_devices;
 		goto out;
 	}

 	nr_devs_want = min_t(unsigned, nr_online, c->opts.metadata_replicas);

 	for (unsigned i = 0; i < journal_space_nr; i++)
 		j->space[i] = __journal_space_available(j, nr_devs_want, i);

 	clean_ondisk	= j->space[journal_space_clean_ondisk].total;
 	clean		= j->space[journal_space_clean].total;
 	total		= j->space[journal_space_total].total;

 	if (!j->space[journal_space_discarded].next_entry)
 		ret = JOURNAL_ERR_journal_full;

 	if ((j->space[journal_space_clean_ondisk].next_entry <
 	     j->space[journal_space_clean_ondisk].total) &&
 	    (clean - clean_ondisk <= total / 8) &&
 	    (clean_ondisk * 2 > clean))
 		set_bit(JOURNAL_may_skip_flush, &j->flags);
 	else
 		clear_bit(JOURNAL_may_skip_flush, &j->flags);

 	bch2_journal_set_watermark(j);
 out:
 	j->cur_entry_sectors	= !ret ? j->space[journal_space_discarded].next_entry : 0;
 	j->cur_entry_error	= ret;

 	if (!ret)
 		journal_wake(j);
 }



